import React from 'react';

import { Link } from 'react-router-dom';

interface IPohLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  href?: string;
}

const PohLink: React.FC<IPohLinkProps> = ({ children, href = '#', onClick, ...rest }) => {
  const handleClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
    href === '#' && event.preventDefault();
    onClick && onClick(event);
  };

  return (
    <>
      {href === '#' || href.indexOf('http') === 0 ? (
        <a onClick={handleClick} href={href} {...rest}>
          {children}
        </a>
      ) : (
        <Link to={href} onClick={handleClick} {...rest}>
          {children}
        </Link>
      )}
    </>
  );
};

export default PohLink;
